namespace Ordering;
/// <summary>In-memory store of orders keyed by their reference.</summary>
public sealed class OrderRepository
{
    public void Add(Order order) => _orders[order.Reference] = order;

    public Order? Get(string reference) => _orders.TryGetValue(reference, out var order) ? order : null;

    public IReadOnlyCollection<Order> ListByCustomer(string customerPrefix)
    {
        var matches = new List<Order>();
        foreach (var order in _orders.Values)
        {
            if (order.Reference.StartsWith(customerPrefix, StringComparison.Ordinal))
                matches.Add(order);
        }
    
        return matches;
    }

    public bool Remove(string reference) => _orders.Remove(reference);

    public int Count => _orders.Count;
}

